const WORLDS={letters:{name:'Letter Lagoon',short:'Letters & reading',sub:'Little letters. Big stories.',asset:'planet-letters.svg',color:'#ad9bdf',bg:'#ede7f8',skill:'Beginning sounds & CVC words',intro:'Every word starts with a little discovery.',text:'Explore letters in familiar words, match capital and lowercase letters, then grow into reading short words.',model:'s · sun',modelText:'Sun starts with the letter s. Say sun slowly with a grown-up. The letter name and its sound are different.',say:'Sun starts with the letter s. Sun. Sock. Both words start with s.'},numbers:{name:'Number Nebula',short:'Numbers & patterns',sub:'Count, connect, discover.',asset:'planet-numbers.svg',color:'#e2b96e',bg:'#faf1de',skill:'Counting, quantities & early sums',intro:'A universe of numbers is waiting.',text:'Start with real groups you can count. Discover more and fewer, build number patterns, and explore small sums.',model:'● ● ●   =   3',modelText:'Point to each dot once: one, two, three. There are three dots altogether.',say:'Point to each dot once. One. Two. Three. There are three dots altogether.'},arabic:{name:'Arabic Oasis',short:'العربية · Arabic',sub:'A new world of words.',asset:'planet-arabic.svg',color:'#76b4a6',bg:'#e7f2ed',skill:'الحروف والكلمات الأولى',intro:'أهلًا بك في واحة الحروف',text:'Explore Arabic letters, vowel marks and familiar words. Read together and notice how a letter changes shape inside a word.',model:'بَ   ·   بَطَّة',modelText:'هذا حرف الباء. مع الفتحة نقرأ بَ كما في بَطَّة.',say:'بَطَّة. تبدأ كلمة بَطَّة بحرف الباء. بَ.'},discovery:{name:'Discovery Planet',short:'Wonder & discovery',sub:'For wonderfully curious minds.',asset:'planet-discovery.svg',color:'#d79aa9',bg:'#f8e9e9',skill:'Nature, shapes & everyday science',intro:'Big questions for little explorers.',text:'Notice shapes, explore living things and use what you know about the world. Look closely, wonder, and try your ideas.',model:'seed → sprout → plant',modelText:'Plants need water and light to grow. Can you find a plant near you? Talk about what you notice.',say:'Plants need water and light to grow. What do you notice about a plant near you?'}};
const KEY='faroug-galaxy-academy-v1', today=()=>{const d=new Date();return `${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`;};
const defaults={name:'Faroug',voice:true,fx:true,music:false,mute:false,voiceEN:'',voiceAR:'',rate:1,voiceSource:'best',voiceRevision:3,voiceVolume:.8,fxVolume:.45,musicVolume:.18,motion:!matchMedia('(prefers-reduced-motion: reduce)').matches,contrast:false,largeText:false,level:'auto',length:6,goal:6,breaks:true};
const fresh=()=>({version:1,settings:{...defaults},stats:{stardust:0,attempted:0,completed:0,independent:0,flights:0,words:0,runs:0,runCoins:0},history:{},sessions:[],daily:{date:today(),count:0},lastWorld:'letters'});
let state=fresh(),storageOK=true;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved?.version===1){state={...fresh(),...saved,settings:{...defaults,...saved.settings,voiceRevision:saved.settings?.voiceRevision||1},stats:{...fresh().stats,...saved.stats}};if(!state.history||typeof state.history!=='object')state.history={};if(!Array.isArray(state.sessions))state.sessions=[];}}catch{storageOK=false;}
// Preserve existing learning progress while replacing the old slowed-down voice default.
if(state.settings.voiceRevision!==3){if(state.settings.rate===.86)state.settings.rate=1;if(state.settings.voiceSource!=='device')state.settings.voiceSource='best';state.settings.voiceRevision=3;}
